function minimumNumbers(num, k) {
  if (num === 0) {
    return 0;
  }
  for (let count = 1; count <= 10; count++) {
    const rest = num - count * k;
    if (rest < 0) {
      return -1;
    }
    if (rest % 10 === 0) {
      return count;
    }
  }
  return -1;
}

