function minimumNumbers(num, k) {
  const parts = [];
  for (let v = 1; v <= num; v++) if (v % 10 === k) parts.push(v);
  const best = new Array(num + 1).fill(Infinity);
  best[0] = 0;
  for (let total = 1; total <= num; total++) {
    for (const v of parts) {
      if (v <= total && best[total - v] + 1 < best[total]) best[total] = best[total - v] + 1;
    }
  }
  return best[num] === Infinity ? -1 : best[num];
}

